import {
  RotateCcw,
  Volume2,
  VolumeX,
  Minus,
  Undo2,
  Copy,
  Check,
  Maximize2,
  Minimize2,
  Sparkles,
  Target,
  Keyboard,
  Sun,
  Moon,
  ChevronDown,
  Vibrate,
} from 'lucide-react';

interface ClickParticle {
  id: number;
  x: number;
  y: number;
  text: string;
}

// Synthesize pleasant, crisp mechanical audio without external assets
class SoundFX {
  private ctx: AudioContext | null = null;

  private getContext(): AudioContext | null {
    if (typeof window === 'undefined') return null;
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
    return this.ctx;
  }

  playClick(pitchMultiplier = 1) {
    const ctx = this.getContext();
    if (!ctx) return;

    try {
      const now = ctx.currentTime;
      // High frequency click transient
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(800 * pitchMultiplier, now);
      osc.frequency.exponentialRampToValueAtTime(140, now + 0.035);

      gain.gain.setValueAtTime(0.25, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.035);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now);
      osc.stop(now + 0.035);

      // Low mechanical thud component
      const subOsc = ctx.createOscillator();
      const subGain = ctx.createGain();
      subOsc.type = 'sine';
      subOsc.frequency.setValueAtTime(180 * pitchMultiplier, now);
      subOsc.frequency.exponentialRampToValueAtTime(60, now + 0.045);

      subGain.gain.setValueAtTime(0.18, now);
      subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.045);

      subOsc.connect(subGain);
      subGain.connect(ctx.destination);

      subOsc.start(now);
      subOsc.stop(now + 0.045);
    } catch {
      // Audio not permitted or interrupted
    }
  }

  playMilestone() {
    const ctx = this.getContext();
    if (!ctx) return;

    try {
      const now = ctx.currentTime;
      const notes = [523.25, 659.25, 783.99, 1046.5]; // C5, E5, G5, C6
      notes.forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const start = now + i * 0.06;

        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, start);

        gain.gain.setValueAtTime(0, start);
        gain.gain.linearRampToValueAtTime(0.2, start + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.28);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start(start);
        osc.stop(start + 0.3);
      });
    } catch {
      // Fallback silent
    }
  }

  playReset() {
    const ctx = this.getContext();
    if (!ctx) return;

    try {
      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(320, now);
      osc.frequency.exponentialRampToValueAtTime(110, now + 0.08);

      gain.gain.setValueAtTime(0.12, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.08);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now);
      osc.stop(now + 0.08);
    } catch {
      // Ignore
    }
  }
}

const sfx = new SoundFX();

export default function App() {
  // Saved count state
  const [count, setCount] = useState<number>(() => {
    try {
      const saved = localStorage.getItem('tally_counter_val');
      return saved ? parseInt(saved, 10) || 0 : 0;
    } catch {
      return 0;
    }
  });

  const [history, setHistory] = useState<number[]>([]);
  const [step, setStep] = useState<number>(1);
  const [soundEnabled, setSoundEnabled] = useState<boolean>(() => {
    try {
      return localStorage.getItem('tally_sound') !== 'false';
    } catch {
      return true;
    }
  });
  const [vibrateEnabled, setVibrateEnabled] = useState<boolean>(true);
  const [targetCount, setTargetCount] = useState<number | null>(() => {
    try {
      const saved = localStorage.getItem('tally_target');
      return saved ? parseInt(saved, 10) : null;
    } catch {
      return null;
    }
  });

  // Theme: 'dark' | 'light'
  const [isDarkMode, setIsDarkMode] = useState<boolean>(() => {
    try {
      return localStorage.getItem('tally_theme') !== 'light';
    } catch {
      return true;
    }
  });

  // UI state
  const [particles, setParticles] = useState<ClickParticle[]>([]);
  const [isPressed, setIsPressed] = useState<boolean>(false);
  const [copied, setCopied] = useState<boolean>(false);
  const [showShortcuts, setShowShortcuts] = useState<boolean>(false);
  const [showTargetModal, setShowTargetModal] = useState<boolean>(false);
  const [targetInput, setTargetInput] = useState<string>('');
  const [showConfirmReset, setShowConfirmReset] = useState<boolean>(false);
  const [isFullscreen, setIsFullscreen] = useState<boolean>(false);
  const [justHitMilestone, setJustHitMilestone] = useState<boolean>(false);

  // Button ref for particle positioning
  const buttonRef = useRef<HTMLButtonElement | null>(null);

  // Save changes
  useEffect(() => {
    try {
      localStorage.setItem('tally_counter_val', count.toString());
    } catch {
      // Ignore localStorage error
    }
  }, [count]);

  useEffect(() => {
    try {
      localStorage.setItem('tally_sound', soundEnabled ? 'true' : 'false');
    } catch {
      // Ignore
    }
  }, [soundEnabled]);

  useEffect(() => {
    try {
      localStorage.setItem('tally_theme', isDarkMode ? 'dark' : 'light');
    } catch {
      // Ignore
    }
  }, [isDarkMode]);

  useEffect(() => {
    try {
      if (targetCount !== null) {
        localStorage.setItem('tally_target', targetCount.toString());
      } else {
        localStorage.removeItem('tally_target');
      }
    } catch {
      // Ignore
    }
  }, [targetCount]);

  // Haptic trigger
  const triggerHaptic = useCallback(() => {
    if (vibrateEnabled && typeof navigator !== 'undefined' && navigator.vibrate) {
      try {
        navigator.vibrate(20);
      } catch {
        // Not supported or blocked
      }
    }
  }, [vibrateEnabled]);

  // Particle spawn
  const spawnParticle = (amount: number, clientX?: number, clientY?: number) => {
    let px = 0;
    let py = 0;

    if (clientX !== undefined && clientY !== undefined && buttonRef.current) {
      const rect = buttonRef.current.getBoundingClientRect();
      px = clientX - rect.left;
      py = clientY - rect.top;
    } else if (buttonRef.current) {
      const rect = buttonRef.current.getBoundingClientRect();
      px = rect.width / 2;
      py = rect.height / 2;
    }

    const newParticle: ClickParticle = {
      id: Date.now() + Math.random(),
      x: px,
      y: py,
      text: amount > 0 ? `+${amount}` : `${amount}`,
    };

    setParticles((prev) => [...prev.slice(-15), newParticle]);

    setTimeout(() => {
      setParticles((prev) => prev.filter((p) => p.id !== newParticle.id));
    }, 700);
  };

  // Increment action
  const handleIncrement = useCallback(
    (e?: React.MouseEvent | React.TouchEvent | React.KeyboardEvent, customStep?: number) => {
      const inc = customStep ?? step;
      setHistory((prev) => [...prev.slice(-40), count]);
      const nextCount = count + inc;
      setCount(nextCount);

      // Sound & Haptic
      if (soundEnabled) {
        // Vary pitch slightly based on count
        const pitch = 1 + (nextCount % 10) * 0.03;
        sfx.playClick(pitch);
      }
      triggerHaptic();

      // Check milestones
      if (
        (targetCount !== null && nextCount === targetCount) ||
        (nextCount > 0 && nextCount % 50 === 0)
      ) {
        if (soundEnabled) sfx.playMilestone();
        setJustHitMilestone(true);
        setTimeout(() => setJustHitMilestone(false), 2000);
      }

      // Spawn floating visual particle
      let clientX: number | undefined;
      let clientY: number | undefined;
      if (e && 'clientX' in e && e.clientX) {
        clientX = e.clientX;
        clientY = e.clientY;
      }
      spawnParticle(inc, clientX, clientY);
    },
    [count, step, soundEnabled, triggerHaptic, targetCount]
  );

  // Decrement action
  const handleDecrement = useCallback(() => {
    if (count <= 0) return;
    setHistory((prev) => [...prev.slice(-40), count]);
    const nextCount = Math.max(0, count - step);
    setCount(nextCount);

    if (soundEnabled) sfx.playClick(0.85);
    triggerHaptic();
    spawnParticle(-step);
  }, [count, step, soundEnabled, triggerHaptic]);

  // Undo action
  const handleUndo = useCallback(() => {
    if (history.length === 0) return;
    const last = history[history.length - 1];
    setHistory((prev) => prev.slice(0, -1));
    setCount(last);
    if (soundEnabled) sfx.playClick(0.9);
    triggerHaptic();
  }, [history, soundEnabled, triggerHaptic]);

  // Reset action
  const handleReset = useCallback(() => {
    setHistory((prev) => [...prev.slice(-40), count]);
    setCount(0);
    setShowConfirmReset(false);
    if (soundEnabled) sfx.playReset();
    triggerHaptic();
  }, [count, soundEnabled, triggerHaptic]);

  // Keyboard shortcut listener
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't trigger if typing in an input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      if (e.code === 'Space' || e.key === 'Enter') {
        e.preventDefault();
        setIsPressed(true);
        handleIncrement();
      } else if (e.key === '-' || e.key === '_') {
        e.preventDefault();
        handleDecrement();
      } else if (e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        setShowConfirmReset(true);
      } else if (e.key === 'z' || e.key === 'Z') {
        if (e.metaKey || e.ctrlKey || e.key === 'z') {
          e.preventDefault();
          handleUndo();
        }
      } else if (e.key === 'm' || e.key === 'M') {
        setSoundEnabled((prev) => !prev);
      } else if (e.key === 'Escape') {
        setShowConfirmReset(false);
        setShowShortcuts(false);
        setShowTargetModal(false);
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.key === 'Enter') {
        setIsPressed(false);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [handleIncrement, handleDecrement, handleUndo]);

  // Copy count to clipboard
  const handleCopy = () => {
    navigator.clipboard.writeText(count.toString()).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  // Toggle fullscreen
  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
      setIsFullscreen(true);
    } else {
      document.exitFullscreen().catch(() => {});
      setIsFullscreen(false);
    }
  };

  // Calculate target progress percentage
  const progressPercent = targetCount && targetCount > 0
    ? Math.min(100, Math.round((count / targetCount) * 100))
    : null;

  return (
    <div
      className={`min-h-screen w-full transition-colors duration-300 flex flex-col justify-between selection:bg-amber-500 selection:text-white ${
        isDarkMode
          ? 'bg-zinc-950 text-zinc-100'
          : 'bg-zinc-50 text-zinc-900'
      }`}
      style={{ userSelect: 'none', WebkitUserSelect: 'none' }}
    >
      {/* Top Navigation Bar */}
      <header className="w-full max-w-4xl mx-auto px-4 sm:px-6 pt-5 pb-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl flex items-center justify-center font-bold text-base shadow-sm border transition-colors bg-amber-500/10 border-amber-500/30 text-amber-500">
            #
          </div>
          <div>
            <h1 className="font-semibold text-sm tracking-tight flex items-center gap-2">
              Tally Counter
              {justHitMilestone && (
                <span className="inline-flex items-center gap-1 text-xs text-amber-400 font-medium animate-bounce">
                  <Sparkles className="w-3.5 h-3.5" /> Milestone!
                </span>
              )}
            </h1>
            <p className={`text-xs ${isDarkMode ? 'text-zinc-500' : 'text-zinc-400'}`}>
              Click or press <kbd className="px-1 py-0.5 rounded font-mono text-[10px] bg-zinc-800 text-zinc-300 border border-zinc-700">Space</kbd>
            </p>
          </div>
        </div>

        {/* Top Control Buttons */}
        <div className="flex items-center gap-1.5 sm:gap-2">
          {/* Target / Goal Button */}
          <button
            onClick={() => {
              setTargetInput(targetCount ? targetCount.toString() : '');
              setShowTargetModal(true);
            }}
            title={targetCount ? `Goal: ${targetCount}` : 'Set Target Goal'}
            aria-label="Set counter goal"
            className={`p-2 rounded-xl transition-all border flex items-center gap-1.5 text-xs font-medium ${
              targetCount
                ? 'bg-amber-500/15 border-amber-500/40 text-amber-500'
                : isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800'
                : 'bg-white border-zinc-200 text-zinc-600 hover:text-zinc-900 hover:bg-zinc-100 shadow-xs'
            }`}
          >
            <Target className="w-4 h-4" />
            {targetCount && <span className="hidden sm:inline font-mono">{progressPercent}%</span>}
          </button>

          {/* Sound Toggle */}
          <button
            onClick={() => setSoundEnabled(!soundEnabled)}
            title={soundEnabled ? 'Mute sound (M)' : 'Enable sound (M)'}
            aria-label={soundEnabled ? 'Mute sound' : 'Enable sound'}
            className={`p-2 rounded-xl transition-all border ${
              soundEnabled
                ? isDarkMode
                  ? 'bg-zinc-900 border-zinc-800 text-amber-400 hover:bg-zinc-800'
                  : 'bg-white border-zinc-200 text-amber-600 hover:bg-zinc-100 shadow-xs'
                : isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-500 hover:text-zinc-300'
                : 'bg-white border-zinc-200 text-zinc-400 hover:text-zinc-600 shadow-xs'
            }`}
          >
            {soundEnabled ? <Volume2 className="w-4 h-4" /> : <VolumeX className="w-4 h-4" />}
          </button>

          {/* Theme Toggle */}
          <button
            onClick={() => setIsDarkMode(!isDarkMode)}
            title={isDarkMode ? 'Switch to light mode' : 'Switch to dark mode'}
            aria-label="Toggle dark/light theme"
            className={`p-2 rounded-xl transition-all border ${
              isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:text-amber-400 hover:bg-zinc-800'
                : 'bg-white border-zinc-200 text-zinc-600 hover:text-amber-600 hover:bg-zinc-100 shadow-xs'
            }`}
          >
            {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
          </button>

          {/* Fullscreen Toggle */}
          <button
            onClick={toggleFullscreen}
            title={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
            aria-label="Toggle fullscreen"
            className={`hidden sm:flex p-2 rounded-xl transition-all border ${
              isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800'
                : 'bg-white border-zinc-200 text-zinc-600 hover:text-zinc-900 hover:bg-zinc-100 shadow-xs'
            }`}
          >
            {isFullscreen ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
          </button>

          {/* Shortcuts Info */}
          <button
            onClick={() => setShowShortcuts(!showShortcuts)}
            title="Keyboard shortcuts"
            aria-label="View keyboard shortcuts"
            className={`p-2 rounded-xl transition-all border ${
              showShortcuts
                ? 'bg-amber-500/20 border-amber-500/40 text-amber-400'
                : isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800'
                : 'bg-white border-zinc-200 text-zinc-600 hover:text-zinc-900 hover:bg-zinc-100 shadow-xs'
            }`}
          >
            <Keyboard className="w-4 h-4" />
          </button>
        </div>
      </header>

      {/* Main Counter Stage */}
      <main className="flex-1 w-full max-w-2xl mx-auto px-4 flex flex-col items-center justify-center py-4">
        {/* Target Progress Bar if target active */}
        {targetCount !== null && (
          <div className="w-full max-w-xs mb-4">
            <div className="flex justify-between items-center text-xs mb-1 font-mono">
              <span className={isDarkMode ? 'text-zinc-400' : 'text-zinc-500'}>
                Goal: {targetCount}
              </span>
              <span className="font-semibold text-amber-500">{progressPercent}%</span>
            </div>
            <div
              className={`w-full h-2 rounded-full overflow-hidden ${
                isDarkMode ? 'bg-zinc-800' : 'bg-zinc-200'
              }`}
            >
              <div
                className="h-full bg-gradient-to-r from-amber-500 to-amber-400 transition-all duration-300 rounded-full"
                style={{ width: `${progressPercent}%` }}
              />
            </div>
          </div>
        )}

        {/* Display Counter Number */}
        <div className="flex flex-col items-center mb-8 relative">
          <div
            onClick={handleCopy}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => e.key === 'Enter' && handleCopy()}
            title="Click to copy number"
            aria-label={`Counter value is ${count}. Click to copy.`}
            className={`cursor-pointer group select-none text-center transition-transform active:scale-95 py-2 px-6 rounded-2xl ${
              isDarkMode ? 'hover:bg-zinc-900/40' : 'hover:bg-zinc-200/50'
            }`}
          >
            <div
              className={`font-mono font-extrabold tracking-tighter tabular-nums leading-none select-none transition-all ${
                count > 99999 ? 'text-6xl sm:text-7xl md:text-8xl' : 'text-7xl sm:text-8xl md:text-9xl'
              } ${
                isDarkMode
                  ? 'text-white drop-shadow-[0_4px_16px_rgba(255,255,255,0.06)]'
                  : 'text-zinc-950 drop-shadow-[0_4px_16px_rgba(0,0,0,0.06)]'
              }`}
            >
              {count.toLocaleString()}
            </div>

            {/* Quick copy tag indicator */}
            <div className="mt-2 flex items-center justify-center gap-1.5 opacity-60 group-hover:opacity-100 transition-opacity text-xs font-mono">
              {copied ? (
                <span className="text-emerald-500 font-medium inline-flex items-center gap-1">
                  <Check className="w-3.5 h-3.5" /> Copied to clipboard!
                </span>
              ) : (
                <span
                  className={`inline-flex items-center gap-1 ${
                    isDarkMode ? 'text-zinc-500' : 'text-zinc-400'
                  }`}
                >
                  <Copy className="w-3.5 h-3.5" /> Click number to copy
                </span>
              )}
            </div>
          </div>
        </div>

        {/* ============================================================== */}
        {/* THE BIG BUTTON */}
        {/* ============================================================== */}
        <div className="relative flex items-center justify-center my-2">
          {/* Floating particle animations */}
          <div className="absolute inset-0 pointer-events-none overflow-visible">
            {particles.map((p) => (
              <span
                key={p.id}
                style={{
                  left: `${p.x}px`,
                  top: `${p.y}px`,
                }}
                className={`absolute pointer-events-none -translate-x-1/2 font-mono font-bold text-2xl select-none animate-float-fade ${
                  p.text.startsWith('-') ? 'text-rose-400' : 'text-amber-400'
                }`}
              >
                {p.text}
              </span>
            ))}
          </div>

          {/* Physical tactile button frame */}
          <div
            className={`p-3 rounded-full transition-all duration-200 ${
              isDarkMode
                ? 'bg-gradient-to-b from-zinc-800 to-zinc-900 shadow-[0_12px_40px_rgba(0,0,0,0.8),inset_0_1px_1px_rgba(255,255,255,0.15)] ring-1 ring-zinc-700/60'
                : 'bg-gradient-to-b from-zinc-200 to-zinc-300 shadow-[0_12px_36px_rgba(0,0,0,0.12),inset_0_1px_1px_rgba(255,255,255,0.8)] ring-1 ring-zinc-300'
            }`}
          >
            <button
              ref={buttonRef}
              type="button"
              aria-label={`Increment counter by ${step}. Current count is ${count}.`}
              onMouseDown={() => setIsPressed(true)}
              onMouseUp={() => setIsPressed(false)}
              onMouseLeave={() => setIsPressed(false)}
              onTouchStart={() => setIsPressed(true)}
              onTouchEnd={() => setIsPressed(false)}
              onClick={(e) => handleIncrement(e)}
              style={{
                touchAction: 'manipulation',
              }}
              className={`relative group w-48 h-48 sm:w-56 sm:h-56 md:w-64 md:h-64 rounded-full flex flex-col items-center justify-center cursor-pointer transition-all duration-75 select-none focus:outline-none focus-visible:ring-4 focus-visible:ring-amber-500/60 ${
                isPressed
                  ? 'translate-y-2.5 scale-[0.98]'
                  : 'hover:scale-[1.015] active:translate-y-2.5 active:scale-[0.98]'
              } ${
                isDarkMode
                  ? isPressed
                    ? 'bg-amber-600 shadow-[0_2px_0_#92400e,inset_0_4px_12px_rgba(0,0,0,0.4)]'
                    : 'bg-gradient-to-b from-amber-500 to-amber-600 shadow-[0_14px_0_#92400e,0_20px_25px_rgba(0,0,0,0.6)]'
                  : isPressed
                  ? 'bg-amber-500 shadow-[0_2px_0_#b45309,inset_0_4px_10px_rgba(0,0,0,0.25)]'
                  : 'bg-gradient-to-b from-amber-400 to-amber-500 shadow-[0_14px_0_#b45309,0_16px_20px_rgba(180,83,9,0.3)]'
              }`}
            >
              {/* Radial glossy highlight inside button */}
              <div
                className={`absolute inset-0 rounded-full pointer-events-none transition-opacity ${
                  isPressed ? 'opacity-20' : 'opacity-40 group-hover:opacity-60'
                } bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-white via-transparent to-transparent`}
              />

              {/* Big Plus / Increment Icon & Text */}
              <div className="relative z-10 flex flex-col items-center justify-center text-white drop-shadow-sm pointer-events-none">
                <span className="text-5xl sm:text-6xl font-black tracking-tight leading-none mb-1">
                  +
                </span>
                <span className="text-base sm:text-lg font-bold tracking-wider uppercase font-mono">
                  {step > 1 ? `ADD ${step}` : 'COUNT'}
                </span>
                <span className="text-[11px] opacity-80 font-medium tracking-wide mt-0.5">
                  TAP OR CLICK
                </span>
              </div>
            </button>
          </div>
        </div>

        {/* Step Selector & Modifier Controls */}
        <div className="mt-8 flex flex-wrap items-center justify-center gap-2 sm:gap-3">
          {/* Step Size Selector */}
          <div
            className={`flex items-center p-1 rounded-xl border ${
              isDarkMode ? 'bg-zinc-900 border-zinc-800' : 'bg-white border-zinc-200 shadow-xs'
            }`}
          >
            {[1, 5, 10, 50].map((val) => (
              <button
                key={val}
                type="button"
                onClick={() => setStep(val)}
                aria-label={`Step increment by ${val}`}
                className={`px-3 py-1.5 text-xs font-mono font-semibold rounded-lg transition-all ${
                  step === val
                    ? 'bg-amber-500 text-white shadow-xs'
                    : isDarkMode
                    ? 'text-zinc-400 hover:text-zinc-200'
                    : 'text-zinc-600 hover:text-zinc-900'
                }`}
              >
                +{val}
              </button>
            ))}
          </div>

          {/* Quick Decrement Button */}
          <button
            type="button"
            onClick={handleDecrement}
            disabled={count <= 0}
            title={`Subtract ${step} (-)`}
            aria-label={`Subtract ${step}`}
            className={`px-3.5 py-2 rounded-xl text-xs font-medium border flex items-center gap-1.5 transition-all disabled:opacity-30 disabled:cursor-not-allowed ${
              isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-300 hover:bg-zinc-800 active:scale-95'
                : 'bg-white border-zinc-200 text-zinc-700 hover:bg-zinc-100 shadow-xs active:scale-95'
            }`}
          >
            <Minus className="w-3.5 h-3.5" />
            <span>-{step}</span>
          </button>

          {/* Undo Button */}
          <button
            type="button"
            onClick={handleUndo}
            disabled={history.length === 0}
            title="Undo last count (Z)"
            aria-label="Undo last change"
            className={`p-2 rounded-xl text-xs border flex items-center transition-all disabled:opacity-30 disabled:cursor-not-allowed ${
              isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800'
                : 'bg-white border-zinc-200 text-zinc-600 hover:text-zinc-900 hover:bg-zinc-100 shadow-xs'
            }`}
          >
            <Undo2 className="w-4 h-4" />
          </button>

          {/* Reset Button */}
          <button
            type="button"
            onClick={() => {
              if (count > 0) {
                setShowConfirmReset(true);
              }
            }}
            disabled={count === 0}
            title="Reset to 0 (R)"
            aria-label="Reset counter to zero"
            className={`p-2 rounded-xl text-xs border flex items-center transition-all disabled:opacity-30 disabled:cursor-not-allowed ${
              isDarkMode
                ? 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:text-rose-400 hover:bg-zinc-800'
                : 'bg-white border-zinc-200 text-zinc-600 hover:text-rose-600 hover:bg-zinc-100 shadow-xs'
            }`}
          >
            <RotateCcw className="w-4 h-4" />
          </button>
        </div>
      </main>

      {/* Footer Info & Shortcuts */}
      <footer className="w-full max-w-4xl mx-auto px-4 py-4 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs">
        <div className="flex items-center gap-3 text-zinc-500 font-mono text-[11px]">
          <span>Steps taken: {history.length}</span>
          <span>·</span>
          <span>Step size: +{step}</span>
          {targetCount !== null && (
            <>
              <span>·</span>
              <span>Remaining: {Math.max(0, targetCount - count)}</span>
            </>
          )}
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowShortcuts(true)}
            className={`text-xs hover:underline flex items-center gap-1 ${
              isDarkMode ? 'text-zinc-500 hover:text-zinc-300' : 'text-zinc-400 hover:text-zinc-700'
            }`}
          >
            <Keyboard className="w-3 h-3" /> Shortcuts
          </button>
        </div>
      </footer>

      {/* Reset Confirmation Modal */}
      {showConfirmReset && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="reset-dialog-title"
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs"
        >
          <div
            className={`w-full max-w-sm p-6 rounded-2xl border shadow-xl animate-in fade-in zoom-in-95 duration-150 ${
              isDarkMode ? 'bg-zinc-900 border-zinc-800 text-white' : 'bg-white border-zinc-200 text-zinc-900'
            }`}
          >
            <h3 id="reset-dialog-title" className="text-base font-semibold mb-1">
              Reset Counter?
            </h3>
            <p className={`text-sm mb-5 ${isDarkMode ? 'text-zinc-400' : 'text-zinc-500'}`}>
              Are you sure you want to reset the count from <strong className="font-mono">{count}</strong> to 0? This can be undone with the undo button.
            </p>
            <div className="flex items-center justify-end gap-2.5">
              <button
                type="button"
                onClick={() => setShowConfirmReset(false)}
                className={`px-4 py-2 text-xs font-medium rounded-xl border ${
                  isDarkMode
                    ? 'border-zinc-700 hover:bg-zinc-800 text-zinc-300'
                    : 'border-zinc-300 hover:bg-zinc-100 text-zinc-700'
                }`}
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleReset}
                className="px-4 py-2 text-xs font-medium rounded-xl bg-rose-600 hover:bg-rose-500 text-white shadow-xs"
              >
                Reset to 0
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Target Goal Setup Modal */}
      {showTargetModal && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="goal-dialog-title"
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs"
        >
          <div
            className={`w-full max-w-sm p-6 rounded-2xl border shadow-xl ${
              isDarkMode ? 'bg-zinc-900 border-zinc-800 text-white' : 'bg-white border-zinc-200 text-zinc-900'
            }`}
          >
            <h3 id="goal-dialog-title" className="text-base font-semibold mb-1">
              Set Target Count
            </h3>
            <p className={`text-xs mb-4 ${isDarkMode ? 'text-zinc-400' : 'text-zinc-500'}`}>
              Track progress toward a target number with a progress bar and milestone chime.
            </p>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                const val = parseInt(targetInput, 10);
                if (!isNaN(val) && val > 0) {
                  setTargetCount(val);
                } else {
                  setTargetCount(null);
                }
                setShowTargetModal(false);
              }}
            >
              <div className="mb-4">
                <label className="block text-xs font-medium mb-1.5 text-zinc-400">
                  Target number (or leave blank to clear)
                </label>
                <input
                  type="number"
                  min="1"
                  step="1"
                  autoFocus
                  placeholder="e.g. 100"
                  value={targetInput}
                  onChange={(e) => setTargetInput(e.target.value)}
                  className={`w-full px-3.5 py-2 rounded-xl text-sm font-mono border focus:outline-none focus:ring-2 focus:ring-amber-500 ${
                    isDarkMode
                      ? 'bg-zinc-800 border-zinc-700 text-white placeholder-zinc-500'
                      : 'bg-zinc-50 border-zinc-300 text-zinc-900 placeholder-zinc-400'
                  }`}
                />
              </div>
              <div className="flex items-center justify-between gap-2">
                {targetCount !== null ? (
                  <button
                    type="button"
                    onClick={() => {
                      setTargetCount(null);
                      setShowTargetModal(false);
                    }}
                    className="text-xs text-rose-500 hover:underline"
                  >
                    Clear Goal
                  </button>
                ) : <span />}
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => setShowTargetModal(false)}
                    className={`px-3 py-1.5 text-xs font-medium rounded-xl border ${
                      isDarkMode
                        ? 'border-zinc-700 hover:bg-zinc-800 text-zinc-300'
                        : 'border-zinc-300 hover:bg-zinc-100 text-zinc-700'
                    }`}
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-4 py-1.5 text-xs font-medium rounded-xl bg-amber-500 hover:bg-amber-400 text-white shadow-xs"
                  >
                    Save
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Keyboard Shortcuts Modal */}
      {showShortcuts && (
        <div
